#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn found_right_half() {
        assert_eq!(search_rotated(&[4, 5, 6, 1, 2, 3], 2), Some(4));
    }

    #[test]
    fn found_left_half() {
        assert_eq!(search_rotated(&[4, 5, 6, 1, 2, 3], 5), Some(1));
    }

    #[test]
    fn missing() {
        assert_eq!(search_rotated(&[4, 5, 6, 1, 2, 3], 7), None);
    }

    #[test]
    fn empty_and_single() {
        assert_eq!(search_rotated(&[], 1), None);
        assert_eq!(search_rotated(&[9], 9), Some(0));
    }

    #[test]
    fn not_rotated_and_large() {
        let nums: Vec<i32> = (0..200000).step_by(2).collect();
        assert_eq!(search_rotated(&nums, 1234), Some(617));
        let mut rot: Vec<i32> = nums[70000..].to_vec();
        rot.extend_from_slice(&nums[..70000]);
        assert_eq!(search_rotated(&rot, 4), Some(nums.len() - 70000 + 2));
        assert_eq!(search_rotated(&rot, 3), None);
    }
}
